const studentBalance = `-- name: StudentBalance :one

SELECT
  (SELECT coalesce(sum(l.amount_cents), 0) FROM invoice_lines l JOIN invoices i ON i.id = l.invoice_id
     WHERE i.student_id = $1 AND i.status = 'issued')::bigint AS invoiced_cents,
  (SELECT coalesce(sum(a.amount_cents), 0) FROM adjustments a WHERE a.student_id = $1 AND a.kind = 'charge')::bigint AS charges_cents,
  (SELECT coalesce(sum(pm.amount_cents), 0) FROM payments pm WHERE pm.student_id = $1 AND pm.status = 'confirmed')::bigint AS paid_cents,
  (SELECT coalesce(sum(a.amount_cents), 0) FROM adjustments a WHERE a.student_id = $1 AND a.kind = 'credit')::bigint AS credits_cents,
  (SELECT coalesce(sum(pm.amount_cents), 0) FROM payments pm WHERE pm.student_id = $1 AND pm.status = 'pending')::bigint AS pending_cents
`

type StudentBalanceRow struct {
	InvoicedCents int64
	ChargesCents  int64
	PaidCents     int64
	CreditsCents  int64
	PendingCents  int64
}

// ---------- balances and reports ----------
// The four sums a balance is made of, and what waits for confirmation.
func (q *Queries) StudentBalance(ctx context.Context, studentID uuid.UUID) (StudentBalanceRow, error) {
	row := q.db.QueryRow(ctx, studentBalance, studentID)
	var i StudentBalanceRow
	err := row.Scan(
		&i.InvoicedCents,
		&i.ChargesCents,
		&i.PaidCents,
		&i.CreditsCents,
		&i.PendingCents,
	)
	return i, err
}

