// Instalments of issued invoices, earliest first, for what is due and when.
func (q *Queries) StudentDueInstalments(ctx context.Context, studentID uuid.UUID) ([]StudentDueInstalmentsRow, error) {
	rows, err := q.db.Query(ctx, studentDueInstalments, studentID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []StudentDueInstalmentsRow{}
	for rows.Next() {
		var i StudentDueInstalmentsRow
		if err := rows.Scan(&i.DueOn, &i.AmountCents, &i.Number); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const studentInvoices = `-- name: StudentInvoices :many
SELECT i.id, i.kind, i.status, i.number, i.created_at, i.issued_at, t.name AS term_name,
       (SELECT coalesce(sum(l.amount_cents), 0) FROM invoice_lines l WHERE l.invoice_id = i.id)::bigint AS total_cents
FROM invoices i
LEFT JOIN academic_terms t ON t.id = i.term_id
WHERE i.student_id = $1 AND (NOT $2::bool OR i.status = 'issued')
ORDER BY i.created_at, i.id
`

